package ai.taskforge.service; import ai.taskforge.domain.*; import ai.taskforge.repo.UserRepository; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service;
@Service public class CurrentUser { private final UserRepository users; public CurrentUser(UserRepository u){users=u;} public AppUser get(){Object p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(p instanceof AppUser u)return u;throw new IllegalStateException("Unauthenticated");} public boolean elevated(){var r=get().getRole();return r==Role.ADMIN||r==Role.MANAGER;} }
